  // dive_rejoin_cd(self) 인라인 (engage.rs:973) = self.last_dive_abandon_tick + 1 + tps*4
  if !(tick > self.last_dive_abandon_tick + 1 + tps*4) → return None                 // L112~113 (어보트 후 4초 쿨다운)
  if version > 1 {                                                                    // L116
